const weather = $input.first().json;
const current = weather.current_condition[0];
const today = weather.weather[0];

const city = 'Roma';
const temp = current.temp_C;
const feelsLike = current.FeelsLikeC;
const description = current.weatherDesc[0].value;
const humidity = current.humidity;
const windSpeed = current.windspeedKmph;
const maxTemp = today.maxtempC;
const minTemp = today.mintempC;

const emojiMap = {
  'Clear': '☀️', 'Sunny': '☀️',
  'Partly cloudy': '⛅️', 'Partly Cloudy': '⛅️',
  'Cloudy': '☁️', 'Overcast': '☁️',
  'Mist': '🌫️', 'Fog': '🌫️',
  'Rain': '🌧️', 'Drizzle': '🌦️', 'Light rain': '🌦️',
  'Snow': '❄️', 'Blizzard': '🌨️',
  'Thunder': '⛈️', 'Thunderstorm': '⛈️'
};

let emoji = '🌤️';
for (const [key, val] of Object.entries(emojiMap)) {
  if (description.includes(key)) { emoji = val; break; }
}

const oggi = new Date().toLocaleDateString('it-IT', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});
const oggiFormatted = oggi.charAt(0).toUpperCase() + oggi.slice(1);

const emailSubject = `${emoji} Meteo di oggi – ${city}`;

const emailBody = `<div style="font-family: Arial, sans-serif; max-width: 520px; margin: 0 auto; padding: 24px; background-color: #f0f7ff; border-radius: 12px;">
  <h2 style="color: #1a5276; margin-bottom: 4px;">${emoji} Buongiorno!</h2>
  <h3 style="color: #2980b9; margin-top: 0; font-size: 20px;">Meteo di oggi – ${city}</h3>
  <p style="color: #666; margin-top: -8px;">📅 ${oggiFormatted}</p>
  <table style="width: 100%; border-collapse: collapse; background: white; border-radius: 8px; overflow: hidden; box-shadow: 0 1px 4px rgba(0,0,0,0.1);">
    <tr style="background-color: #d6eaf8;">
      <td style="padding: 12px 16px;">🌡️ <strong>Temperatura</strong></td>
      <td style="padding: 12px 16px;"><strong>${temp}°C</strong> &nbsp;(percepita ${feelsLike}°C)</td>
    </tr>
    <tr>
      <td style="padding: 12px 16px;">📊 <strong>Min / Max</strong></td>
      <td style="padding: 12px 16px;">${minTemp}°C &nbsp;/&nbsp; ${maxTemp}°C</td>
    </tr>
    <tr style="background-color: #d6eaf8;">
      <td style="padding: 12px 16px;">🌥️ <strong>Condizioni</strong></td>
      <td style="padding: 12px 16px;">${description}</td>
    </tr>
    <tr>
      <td style="padding: 12px 16px;">💧 <strong>Umidità</strong></td>
      <td style="padding: 12px 16px;">${humidity}%</td>
    </tr>
    <tr style="background-color: #d6eaf8;">
      <td style="padding: 12px 16px;">💨 <strong>Vento</strong></td>
      <td style="padding: 12px 16px;">${windSpeed} km/h</td>
    </tr>
  </table>
  <p style="color: #aaa; font-size: 11px; margin-top: 18px; text-align: center;">Dati meteo forniti da <a href="https://wttr.in" style="color: #aaa;">wttr.in</a> · Inviato automaticamente da n8n</p>
</div>`;

return [{ json: { emailSubject, emailBody, city, temp, description } }];
